"""Resolve a logical training record to its backing file."""
import json
from pathlib import Path


def resolve(root, record):
    base = Path(root)
    target_sha = record.get('sha256')
    target_id = record.get('id')
    target_diff = record.get('difficulty')
    target_line = record.get('source_line')
    if not target_sha:
        raise ValueError('Missing target sha256')

    candidates = []
    rec_path = record.get('path')
    if isinstance(rec_path, str) and rec_path:
        candidates.append(rec_path)
        if rec_path.startswith('live/hard/'):
            candidates.append(rec_path.replace('live/hard/', 'archive/hard/'))

    catalog_file = base / 'catalog.json'
    if catalog_file.is_file():
        catalog = json.loads(catalog_file.read_text())
        rows = catalog.get('rows')
        if isinstance(rows, list):
            for row in rows:
                if isinstance(row, dict) and row.get('sha256') == target_sha:
                    if not target_id or row.get('id') == target_id:
                        row_path = row.get('path')
                        if isinstance(row_path, str) and row_path and row_path not in candidates:
                            candidates.append(row_path)

    for rel in candidates:
        candidate = base / rel
        if candidate.is_file():
            payload = json.loads(candidate.read_text())
            if isinstance(payload, dict):
                meta = payload.get('metadata')
                if not isinstance(meta, dict):
                    meta = {}
                if not target_id or payload.get('id') == target_id:
                    if not target_diff or meta.get('difficulty') == target_diff:
                        if target_line is None or meta.get('source_line') == target_line:
                            return candidate.relative_to(base)

    raise FileNotFoundError('Requested record unavailable')

